export default async function find({root,company,month,previous},context){
 if(!root||root.startsWith('YOUR_'))throw Error('Configure parent Drive folder');const init={phase:'company',parent:root,token:null,seen:[],found:null};let s=previous??init;if(!['company','month'].includes(s.phase))throw Error('Invalid folder state');const name=s.phase==='company'?company:month;if(typeof name!=='string'||!name)throw Error('Missing folder name');const esc=x=>x.replace(/\\/g,'\\\\').replace(/'/g,"\\'");const q=`mimeType = 'application/vnd.google-apps.folder' and trashed = false and name = '${esc(name)}' and '${esc(s.parent)}' in parents`;const page=await context.actions.call('googledrive.files.list',{q,pageSize:1000,...(s.token?{pageToken:s.token}:{})});if(!Array.isArray(page.files))throw Error('Invalid folder page');let found=s.found;for(const f of page.files){if(!f||typeof f.id!=='string'||!f.id||f.name!==name||f.mimeType!=='application/vnd.google-apps.folder')throw Error('Invalid folder search result');if(found&&found!==f.id)throw Error('Ambiguous duplicate folders');found=f.id}const token=page.nextPageToken;if(token!==null&&(typeof token!=='string'||!token||s.seen.includes(token)))throw Error('Invalid folder page cursor');if(token!==null)return {state:{...s,token,found,seen:[...s.seen,token]},more:true,folderId:''};if(!found){const result=await context.actions.call('googledrive.files.create',{name,mimeType:'application/vnd.google-apps.folder',parents:[s.parent]});if(!result||typeof result.id!=='string'||!result.id)throw Error('Folder create was not confirmed');found=result.id}if(s.phase==='company')return {state:{phase:'month',parent:found,token:null,seen:[],found:null},more:true,folderId:''};return {state:init,more:false,folderId:found};
}

